CREATE FUNCTION public.sync_support_request_thread() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.support_ticket_messages(ticket_id,sender_id,sender_role,body) VALUES(NEW.id,NEW.user_id,'requester',NEW.message); ELSIF NEW.admin_reply IS DISTINCT FROM OLD.admin_reply AND nullif(btrim(NEW.admin_reply),'') IS NOT NULL AND pg_trigger_depth()=1 THEN INSERT INTO public.support_ticket_messages(ticket_id,sender_id,sender_role,body) VALUES(NEW.id,auth.uid(),'admin',NEW.admin_reply); END IF; RETURN NEW; END $$;
CREATE TRIGGER support_request_thread AFTER INSERT OR UPDATE OF admin_reply ON public.support_requests FOR EACH ROW EXECUTE FUNCTION public.sync_support_request_thread();
REVOKE ALL ON FUNCTION public.sync_support_request_thread() FROM PUBLIC,anon,authenticated;